package com.mg.fixturecockpitsim;
import android.content.Context;import android.graphics.Canvas;import android.graphics.Paint;import android.graphics.Path;import android.view.View;
/** AVM-8.5 airport/hangar/taxiway plus 300 second scenic route. */
public final class RunwayHudView extends View{
 private final Paint f=new Paint(3),l=new Paint(3);private final Path p=new Path();private volatile float altitudeM,speedMps,route,groundProgress,headingDeg;private volatile boolean onGround,demoMode;private volatile String phase="";private float scroll;private long last;
 public RunwayHudView(Context c){super(c);setWillNotDraw(false);f.setStyle(Paint.Style.FILL);l.setStyle(Paint.Style.STROKE);l.setStrokeCap(Paint.Cap.ROUND);}
 public void setDemoMode(boolean e){demoMode=e;postInvalidateOnAnimation();}public void setDemoProgress(double s){route=(float)Math.max(0,s);postInvalidateOnAnimation();}public void setGroundProgress(double q,double hdg){groundProgress=(float)Math.max(0,Math.min(1,q));headingDeg=(float)hdg;postInvalidateOnAnimation();}public void setFlightState(double a,double s,boolean g,String ph){altitudeM=(float)Math.max(0,a);speedMps=(float)Math.max(0,s);onGround=g;phase=ph==null?"":ph;postInvalidateOnAnimation();}
 protected void onDraw(Canvas c){super.onDraw(c);long n=System.nanoTime();float dt=last==0?.016f:Math.min(.05f,(n-last)/1e9f);last=n;scroll=(scroll+speedMps*dt*.02f)%1;int w=getWidth(),h=getHeight();float hz=h*(.47f+.07f*Math.min(1,altitudeM/1200));sky(c,w,h,hz);airport(c,w,h,hz);if(phase.contains("HANGAR")){hangar(c,w,h,hz);return;}if(phase.contains("TAXI")){taxiway(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();return;}if(demoMode&&phase.contains("ORBIT")){scenery(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();return;}boolean rw=onGround||phase.contains("RUNWAY")||phase.contains("TAKEOFF")||phase.contains("ROTATE")||phase.contains("APPROACH")||phase.contains("FLARE")||phase.contains("ROLLOUT")||phase.contains("COMPLETE");if(!rw)return;runway(c,w,h,hz);if(speedMps>1)postInvalidateOnAnimation();}
 private void sky(Canvas c,int w,int h,float hz){f.setColor(0xff14283d);c.drawRect(0,0,w,hz,f);f.setColor(0x443b6781);c.drawRect(0,hz-h*.10f,w,hz,f);}
 private void hangar(Canvas c,int w,int h,float hz){float q=groundProgress;f.setColor(0xff454a4d);c.drawRect(0,hz,w,h,f);f.setColor(0xff24292d);c.drawRect(w*.10f,hz-h*.23f,w*.90f,hz+h*.36f,f);f.setColor(0xff69737a);c.drawRect(w*.15f,hz-h*.16f,w*.85f,hz+h*.34f,f);float doorOpen=.18f+.82f*q;float cx=w*.5f,doorHalf=w*.24f;f.setColor(0xff1b2024);c.drawRect(cx-doorHalf*doorOpen,hz-h*.08f,cx+doorHalf*doorOpen,hz+h*.33f,f);l.setColor(0xff8d979e);l.setStrokeWidth(3);for(int i=0;i<7;i++){float x=lerp(w*.15f,w*.85f,i/6f);c.drawLine(x,hz-h*.16f,x,hz+h*.34f,l);}f.setColor(0xffffd55a);for(int i=0;i<8;i++)c.drawCircle(w*(.28f+i*.063f),hz-h*.02f,4,f);l.setColor(0xffe9c43e);l.setStrokeWidth(5);c.drawLine(cx,hz+h*.33f,cx,h,l);f.setColor(0xfff1f1f1);f.setTextSize(Math.max(22,w*.028f));c.drawText(q<.45f?"HANGAR 01 • MOTOR START":"HANGAR 01 • TAXI CLEARANCE",w*.05f,h*.88f,f);}
 private void taxiway(Canvas c,int w,int h,float hz){float q=groundProgress;f.setColor(0xff263628);c.drawRect(0,hz,w,h,f);float join=q*q;float bend=1f-join;p.reset();p.moveTo(w*(.18f+.20f*join),h);p.cubicTo(w*(.28f+.10f*join),h*.78f,w*(.50f+.02f*join),h*.68f,w*.49f,hz+h*.04f);p.lineTo(w*.61f,hz+h*.04f);p.cubicTo(w*(.63f-.02f*join),h*.69f,w*(.45f+.12f*join),h*.82f,w*(.38f+.20f*join),h);p.close();f.setColor(0xff53585b);c.drawPath(p,f);l.setColor(0xfff0c928);l.setStrokeWidth(4);p.reset();p.moveTo(w*(.29f+.19f*join),h);p.cubicTo(w*(.36f+.12f*join),h*.79f,w*(.55f+.03f*join),h*.70f,w*.55f,hz+h*.04f);c.drawPath(p,l);
  for(int i=0;i<12;i++){float z=i/11f,y=hz+h*(.04f+.78f*z*z),x=w*(.55f-.25f*z+.17f*join*z);f.setColor(0xff4ea2ff);c.drawCircle(x-w*.08f,y,2+3*z,f);c.drawCircle(x+w*.08f,y,2+3*z,f);}if(q>.62f){float a=(q-.62f)/.38f;float rwx=w*(.64f+.05f*a);f.setColor(0xff35383a);c.drawRect(rwx,hz+h*.03f,w,h,f);l.setColor(0xffffffff);l.setStrokeWidth(3);c.drawLine(rwx+w*.05f,hz+h*.04f,w*.93f,h*.98f,l);}
  f.setColor(0xfff7df53);f.setTextSize(Math.max(18,w*.022f));c.drawText(q<.67f?"TAXI A":"RWY 27 • LINE UP",w*.64f,hz+h*.18f,f);f.setColor(0xe8ffffff);f.setTextSize(Math.max(15,w*.017f));c.drawText("HDG "+Math.round((headingDeg%360+360)%360)+"°",w*.64f,hz+h*.23f,f);}
 private void runway(Canvas c,int w,int h,float hz){float near=1-Math.min(1,altitudeM/950),fh=w*(.022f+.01f*near),nh=w*(onGround?.45f:(.14f+.28f*near)),fy=hz+h*(.012f+.018f*near),ny=h*(onGround?.995f:(.70f+.28f*near)),cx=w*.5f;f.setColor(0xff293326);c.drawRect(0,hz,w,h,f);p.reset();p.moveTo(cx-fh*1.4f,fy);p.lineTo(cx+fh*1.4f,fy);p.lineTo(cx+nh*1.14f,ny);p.lineTo(cx-nh*1.14f,ny);p.close();f.setColor(0xff6b6d6b);c.drawPath(p,f);p.reset();p.moveTo(cx-fh,fy);p.lineTo(cx+fh,fy);p.lineTo(cx+nh,ny);p.lineTo(cx-nh,ny);p.close();f.setColor(0xff343638);c.drawPath(p,f);for(int i=1;i<17;i++){float q=i/17f,z=q*q,y=lerp(fy,ny,z),half=lerp(fh,nh,z);l.setColor(0x30202526);l.setStrokeWidth(2);c.drawLine(cx-half*.96f,y,cx+half*.96f,y,l);}l.setColor(0xfff5f4ef);l.setStrokeWidth(Math.max(2,w*.0024f));c.drawLine(cx-fh,fy,cx-nh,ny,l);c.drawLine(cx+fh,fy,cx+nh,ny,l);for(int i=0;i<18;i++){float q=(i+scroll)/18;q-=Math.floor(q);float z=q*q,y=lerp(fy,ny,z);l.setStrokeWidth(2+12*z);l.setColor(0xffffffff);c.drawLine(cx,y,cx,y+5+30*z,l);}for(int i=0;i<25;i++){float q=i/24f,z=q*q,y=lerp(fy,ny,z),half=lerp(fh,nh,z),r=1+4*z;f.setColor(i>20?0xffffd54f:0xfff7f3df);c.drawCircle(cx-half,y,r,f);c.drawCircle(cx+half,y,r,f);}float z=.82f+.1f*near,y=lerp(fy,ny,z),half=lerp(fh,nh,z);f.setColor(0xffffffff);for(int i=-4;i<=4;i++)if(i!=0)c.drawRect(cx+i*half*.105f-half*.035f,y,cx+i*half*.105f+half*.035f,y+25+35*near,f);f.setTextAlign(Paint.Align.CENTER);f.setTextSize(Math.max(28,w*.04f));c.drawText("27",cx,Math.min(ny-15,y+85),f);f.setTextAlign(Paint.Align.LEFT);float py=lerp(fy,ny,.58f),ph=lerp(fh,nh,.58f);for(int i=0;i<4;i++){f.setColor(i<2?0xffff3b30:0xffffffff);c.drawCircle(cx-ph*1.2f+i*10,py,4,f);}l.setColor(0xffe5bd39);l.setStrokeWidth(3);p.reset();p.moveTo(cx+ph,py);p.quadTo(w*.80f,py+h*.05f,w,py+h*.08f);c.drawPath(p,l);for(int i=0;i<9;i++){f.setColor(0xffffffff);c.drawCircle(cx,fy-(fy-hz)*(.08f+.06f*i),2,f);}}
 private void airport(Canvas c,int w,int h,float hz){f.setColor(0xff344236);c.drawRect(0,hz,w,hz+h*.12f,f);f.setColor(0xff4b5151);for(int i=0;i<7;i++){float x=w*(.025f+i*.055f),bh=h*(.018f+(i%3)*.008f);c.drawRect(x,hz-bh,x+w*.04f,hz,f);}float x=w*.80f;f.setColor(0xff4b5154);c.drawRect(x-5,hz-h*.075f,x+5,hz,f);c.drawRect(x-16,hz-h*.086f,x+16,hz-h*.068f,f);f.setColor(0xffffd76c);for(int i=0;i<18;i++)c.drawCircle(w*(.02f+i*.055f),hz-2,1.5f,f);}
 private void scenery(Canvas c,int w,int h,float hz){float t=Math.min(300,route);String label;if(t<45){label="SAHİL ÜZERİ TIRMANIŞ";coast(c,w,h,hz,.25f);}else if(t<90){label="DAĞLARA YAKLAŞMA";mountains(c,w,h,hz,.45f,false);}else if(t<145){label="VADİ İÇİ UÇUŞ";mountains(c,w,h,hz,.72f,true);}else if(t<205){label="DAĞ YOLU TAKİBİ";mountains(c,w,h,hz,.92f,true);road(c,w,h,hz);}else if(t<250){label="GÖL / KIYI GEÇİŞİ";lake(c,w,h,hz);}else if(t<280){label="YÜKSEK ARAZİ / DÖNÜŞ";mountains(c,w,h,hz,.68f,false);}else{label="HAVALİMANINA DÖNÜŞ";mountains(c,w,h,hz,.35f,false);airport(c,w,h,hz);}f.setColor(0xe8ffffff);f.setTextSize(Math.max(20,w*.022f));c.drawText(label,w*.04f,h*.88f,f);}
 private void mountains(Canvas c,int w,int h,float hz,float scale,boolean valley){p.reset();p.moveTo(0,h);for(int i=0;i<=12;i++){float x=w*i/12f,y=hz-h*scale*(.05f+.13f*(float)Math.abs(Math.sin(i*1.37+route*.012)));if(valley&&i>4&&i<8)y+=h*.13f;p.lineTo(x,y);}p.lineTo(w,h);p.close();f.setColor(0xff425344);c.drawPath(p,f);p.reset();p.moveTo(0,h);for(int i=0;i<=10;i++){float x=w*i/10f,y=hz+h*.05f-h*scale*.08f*(float)Math.abs(Math.sin(i*1.8+.8));p.lineTo(x,y);}p.lineTo(w,h);p.close();f.setColor(0xff304039);c.drawPath(p,f);}
 private void coast(Canvas c,int w,int h,float hz,float q){mountains(c,w,h,hz,q,false);f.setColor(0xff315d70);c.drawRect(0,hz+h*.12f,w,h,f);l.setColor(0x885f98ad);l.setStrokeWidth(2);for(int i=0;i<8;i++)c.drawLine(0,hz+h*(.15f+i*.05f),w,hz+h*(.15f+i*.05f),l);}
 private void lake(Canvas c,int w,int h,float hz){mountains(c,w,h,hz,.55f,true);f.setColor(0xff315f72);p.reset();p.moveTo(w*.15f,h);p.lineTo(w*.32f,hz+h*.15f);p.lineTo(w*.67f,hz+h*.12f);p.lineTo(w*.90f,h);p.close();c.drawPath(p,f);}
 private void road(Canvas c,int w,int h,float hz){l.setColor(0xff737673);l.setStrokeWidth(Math.max(10,w*.018f));p.reset();p.moveTo(w*.15f,h);p.cubicTo(w*.40f,h*.70f,w*.36f,h*.58f,w*.58f,hz+h*.08f);c.drawPath(p,l);l.setColor(0xffe2c94a);l.setStrokeWidth(2);c.drawPath(p,l);}
 private static float lerp(float a,float b,float t){return a+(b-a)*t;}
}
